import{_ as o,c as t,o as d,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"小程式","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/miniapps.md","filePath":"zh-TW/guide/miniapps.md","lastUpdated":1791311600000}'),a={name:"zh-TW/guide/miniapps.md"};function c(i,e,l,n,s,h){return d(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="小程式" tabindex="-1">小程式 <a class="header-anchor" href="#小程式" aria-label="Permalink to &quot;小程式&quot;">​</a></h1><p>nPlyr 可以執行 <strong>hikerView 相容的小程式</strong>——也就是為 Android 應用程式提供動力的同一批社群規則。本頁解釋它們是什麼，以及 nPlyr 如何執行它們。關於相容性邊界（尤其是 Java/Rhino 部分），請閱讀<a href="/zh-TW/guide/miniapp-compatibility.html">相容性</a>頁面。</p><h2 id="什麼是小程式" tabindex="-1">什麼是小程式？ <a class="header-anchor" href="#什麼是小程式" aria-label="Permalink to &quot;什麼是小程式？&quot;">​</a></h2><p>在這個生態中，小程式是一個<strong>規則包</strong>（HTML + JavaScript），它告訴應用程式如何：</p><ul><li>渲染一個分類 / 頻道的<strong>首頁</strong>，</li><li>執行一次<strong>搜尋</strong>，</li><li>解析一個<strong>列表</strong>頁與一個<strong>詳情</strong>頁，並</li><li>提取<strong>可播放連結</strong>交給播放器。</li></ul><p>規則邏輯執行在 JavaScript 引擎中，並透過一個名為 <strong><code>fy_bridge_app</code></strong>（簡稱 <strong><code>fba</code></strong>）的橋接物件與宿主應用程式通訊。</p><h2 id="nplyr-重新實作的契約" tabindex="-1">nPlyr 重新實作的契約 <a class="header-anchor" href="#nplyr-重新實作的契約" aria-label="Permalink to &quot;nPlyr 重新實作的契約&quot;">​</a></h2><p>nPlyr <strong>不</strong>移植 hikerView 的 Android/Java UI。相反，它複用了真正承載價值的層次——<strong>規則引擎、解析 DSL 與小程式橋接契約</strong>——並為 Apple 平台原生重寫了 UI、WebView 與網路層。</p><p>具體而言，nPlyr 提供了以下內容的原生實作：</p><ul><li><strong>規則 DSL</strong>：<code>pdfh</code> / <code>pdfa</code> / <code>pd</code> 選擇器、<code>parseDom</code>、<code>setHomeResult</code>、<code>setSearchResult</code>、<code>setResult</code>；</li><li><strong><code>$</code> 選擇器相容層</strong>，使 <code>$(url).lazyRule(fn)</code> 與 <code>$(url, ordinary).lazyRule</code> 表現得符合預期；</li><li><strong><code>fy_bridge_app</code> / <code>fba</code> 橋</strong>，使規則可以呼叫宿主功能：播放、fetch、post、解析、儲存變數；</li><li><strong><code>hiker://</code> 偽協定</strong>路由（包括作為輕量參數載體的 <code>hiker://empty##…</code>，以及用於聚合搜尋的 <code>hiker://search?s=</code>）；</li><li><strong><code>lazyRule</code> / <code>.rule(fn)</code></strong> 執行模型、頁面導覽（<code>beginResultNavigation</code> / <code>finalizeResultPage</code>）以及結果堆疊生命週期（<code>onClose</code> 歸屬、<code>MY_PAGE</code> 歸屬）。</li></ul><h2 id="規則-dsl-要點" tabindex="-1">規則 DSL 要點 <a class="header-anchor" href="#規則-dsl-要點" aria-label="Permalink to &quot;規則 DSL 要點&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>用途</th></tr></thead><tbody><tr><td><code>setHomeResult([…])</code></td><td>輸出首頁網格（分類 / 頻道）。</td></tr><tr><td><code>setSearchResult([…])</code></td><td>輸出搜尋結果。</td></tr><tr><td><code>lazyRule</code> / <code>.rule(fn)</code></td><td>執行子規則以解析列表 / 詳情頁。</td></tr><tr><td><code>fetch</code> / <code>post</code></td><td>帶請求標頭的 HTTP；<code>withHeaders</code> / <code>onlyHeaders</code> / <code>withStatusCode</code> 回傳 JSON 信封。</td></tr><tr><td><code>putVar</code> / <code>getVar</code> / <code>putMyVar</code> / <code>getMyVar</code></td><td>記憶體變數；<code>setItem</code> / <code>getItem</code> / <code>clearItem</code> 持久化到本機儲存。</td></tr><tr><td><code>MY_URL</code> / <code>MY_RULE</code></td><td>目前規則的 URL 與規則主體。</td></tr><tr><td><code>AES</code> / <code>RSA</code> / <code>CryptoJS</code></td><td>規則可用的加密輔助。</td></tr></tbody></table><p>每個列表項目都帶有一個 <code>col_type</code>，nPlyr 將其對應到 SwiftUI 佈局——共有 <strong>38 種 <code>col_type</code> 佈局</strong>（如 <code>text_1</code>、<code>pic_19</code>），與 hikerView 自有的項目範本對齊，因此現有規則會如其作者所預期的那樣渲染。</p><h2 id="管理小程式" tabindex="-1">管理小程式 <a class="header-anchor" href="#管理小程式" aria-label="Permalink to &quot;管理小程式&quot;">​</a></h2><p>打開<strong>小程式</strong>（macOS 上的管理器視窗；iOS 上的分頁 / 頁面）以：</p><ul><li>從分享文字或 JSON <strong>匯入</strong>一個程式，</li><li><strong>新增 / 編輯</strong>一條規則（macOS 上是完整規則編輯器；iOS 上是一個 Push 頁面），</li><li><strong>重新排列</strong>程式（拖拽）——首頁頂列跟隨該順序，</li><li><strong>刪除</strong>一個程式，</li><li><strong>分享 / 雲端分享</strong>一個程式（雲端後端：TextDB、<code>cmd.im</code> 302 重新導向，以及 <code>pasteme</code>）。</li></ul><p><strong>免費層級</strong>會限制匯入的小程式數量；一次性解鎖會移除該限制。</p><h2 id="搜尋" tabindex="-1">搜尋 <a class="header-anchor" href="#搜尋" aria-label="Permalink to &quot;搜尋&quot;">​</a></h2><p>獨立的搜尋視窗由你已安裝且宣告了 <code>search_url</code> 的規則建構而成。你可以搜尋單一引擎，也可以跨所有引擎聚合搜尋。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/zh-TW/guide/miniapp-compatibility.html">相容性</a>——具體哪些 Java/Rhino 行為被支援、哪些不被支援。</li><li><a href="/zh-TW/guide/downloads.html">下載與媒體庫</a>——解析出的連結去向何處。</li><li><a href="/zh-TW/guide/browser.html">瀏覽器與嗅探器</a>——擷取連結的另一條路徑。</li></ul><h2 id="海闊視界官方文件" tabindex="-1">海闊視界官方文件 <a class="header-anchor" href="#海闊視界官方文件" aria-label="Permalink to &quot;海闊視界官方文件&quot;">​</a></h2><p>nPlyr 旨在與 hikerView 規則生態相容。關於完整的規則與小程式參考——DSL、選擇器、橋接契約與編寫指南——請參閱海闊視界官方文件：</p><ul><li><strong>海闊視界文件：</strong> <a href="https://github.com/ReflectionLab/Documents" target="_blank" rel="noreferrer">https://github.com/ReflectionLab/Documents</a></li></ul><p>如果你已經為 hikerView 編寫規則，同樣的分享文字與 JSON 在 nPlyr 中可直接匯入並執行（受上述相容性邊界約束）。</p>',25)])])}const u=o(a,[["render",c]]);export{g as __pageData,u as default};
